package com.alchmatepro;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Immutable financial calculation output produced by ProfitCalculator.
 * Uses 64-bit integer GP arithmetic to prevent 32-bit integer overflow on bulk quantities.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class AlchCalculation
{
	private int itemId;
	private int quantity;

	private long highAlchValuePerItem;
	private long purchaseCostPerItem;
	private long natureRuneCostPerCast;
	private long fireRuneCostPerCast;
	private long otherCostPerCast;

	private long totalCostPerAlch;
	private long netProfitPerAlch;

	private long grossAlchemyReturn;
	private long totalPurchaseCost;
	private long totalNatureRuneExpenditure;
	private long totalFireRuneExpenditure;
	private long totalOtherExpenditure;
	private long totalInvestment;
	private long totalNetProfit;

	private double roiPercent;
	private double totalReturnRatioPercent;

	private long breakEvenPurchasePrice;
	private long maxAffordablePurchasePrice;

	private int geBuyLimit4h;
	private long maxBuyLimitInvestment;
	private long maxBuyLimitProfit4h;
	private int maxBuyLimitNatureRunes;

	private long profitPer100Alchs;
	private long profitPer1000Alchs;

	private boolean valid;
	private String validationMessage;

	public boolean isProfitable()
	{
		return valid && netProfitPerAlch > 0;
	}

	public long getLossPerAlch()
	{
		if (!valid || netProfitPerAlch >= 0)
		{
			return 0L;
		}
		return Math.abs(netProfitPerAlch);
	}
}

package com.alchmatepro;

import java.util.Collections;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Enriched item domain model combining metadata, live market pricing, calculation results,
 * freshness metadata, and smart recommendation telemetry.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class AlchMateItem
{
	private ItemMetadata metadata;
	private MarketPrice marketPrice;
	private AlchCalculation calculation;
	private AlchRecommendation recommendation;

	private long estimatedPurchasePrice;
	private PriceSourceType priceSourceType;
	private boolean stale;
	private long priceAgeSeconds;

	public int getId()
	{
		return metadata != null ? metadata.getId() : 0;
	}

	public String getName()
	{
		return metadata != null && metadata.getName() != null ? metadata.getName() : "Unknown Item";
	}

	public boolean isMembers()
	{
		return metadata != null && metadata.isMembers();
	}

	public int getHighAlchValue()
	{
		return metadata != null ? metadata.getHighAlchValue() : 0;
	}

	public int getLowAlchValue()
	{
		return metadata != null ? metadata.getLowAlchValue() : 0;
	}

	public int getBuyLimit()
	{
		return metadata != null ? metadata.getBuyLimit() : 0;
	}

	public long getNetProfitPerAlch()
	{
		return calculation != null && calculation.isValid() ? calculation.getNetProfitPerAlch() : 0L;
	}

	public double getRoiPercent()
	{
		return calculation != null && calculation.isValid() ? calculation.getRoiPercent() : 0.0;
	}

	public int getVolume1h()
	{
		return marketPrice != null ? marketPrice.getTotalVolume1h() : 0;
	}

	public int getVolume5m()
	{
		return marketPrice != null ? marketPrice.getTotalVolume5m() : 0;
	}

	public boolean hasValidPrice()
	{
		return calculation != null && calculation.isValid() && estimatedPurchasePrice > 0;
	}

	public boolean isProfitable()
	{
		return hasValidPrice() && calculation.getNetProfitPerAlch() > 0;
	}

	public List<MarketWarning> getWarnings()
	{
		return recommendation != null && recommendation.getWarnings() != null
			? recommendation.getWarnings()
			: Collections.emptyList();
	}

	public String getFreshnessLabel()
	{
		if (!hasValidPrice() || priceAgeSeconds == Long.MAX_VALUE)
		{
			return "Unknown age";
		}
		if (priceAgeSeconds < 60)
		{
			return priceAgeSeconds + "s ago";
		}
		long minutes = priceAgeSeconds / 60;
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		long hours = minutes / 60;
		if (hours < 48)
		{
			return hours + "h ago";
		}
		return (hours / 24) + "d ago";
	}
}

package com.alchmatepro;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * Persistent RuneLite configuration interface for AlchMate Pro.
 */
@ConfigGroup(AlchMateProConfig.CONFIG_GROUP)
public interface AlchMateProConfig extends Config
{
	String CONFIG_GROUP = "alchmatepro";
	String WATCHLIST_DATA_KEY = "watchlistJson";
	String CACHED_MAPPING_KEY = "cachedMappingJson";
	String CACHED_PRICES_KEY = "cachedPricesJson";

	@ConfigSection(
		name = "Rune & Cast Costs",
		description = "Configure nature rune, fire rune, and alchemy casting expenditure",
		position = 0
	)
	String costSection = "costSection";

	@ConfigSection(
		name = "Pricing & Market Safety",
		description = "Configure price calculation methodology, freshness thresholds, and auto-refresh",
		position = 1
	)
	String pricingSection = "pricingSection";

	@ConfigSection(
		name = "Scanner Defaults & Filters",
		description = "Configure default scanner filters, quantities, and sorting preferences",
		position = 2
	)
	String scannerSection = "scannerSection";

	@ConfigSection(
		name = "Alerts & Notifications",
		description = "Configure profit alerts, ROI triggers, and notification cooldowns",
		position = 3
	)
	String alertSection = "alertSection";

	// ==================== RUNE & CAST COSTS ====================

	@ConfigItem(
		keyName = "useLiveNatureRunePrice",
		name = "Use Live Nature Rune Price",
		description = "Automatically use the live Grand Exchange price for Nature runes (Item ID 561), falling back to the manual cost below if unavailable",
		position = 1,
		section = costSection
	)
	default boolean useLiveNatureRunePrice()
	{
		return true;
	}

	@Range(min = 0, max = 10000)
	@ConfigItem(
		keyName = "natureRuneCost",
		name = "Nature Rune Cost (GP)",
		description = "Cost of 1 Nature rune per High Level Alchemy cast (used when Live Nature Rune Price is off, or as fallback)",
		position = 2,
		section = costSection
	)
	default int natureRuneCost()
	{
		return 150;
	}

	@ConfigItem(
		keyName = "useFireStaff",
		name = "Equipped Fire Staff (0 Fire Rune Cost)",
		description = "When enabled, assumes a Staff of Fire / Lava battlestaff / Tome of Fire is equipped so Fire rune cost is 0 GP",
		position = 3,
		section = costSection
	)
	default boolean useFireStaff()
	{
		return true;
	}

	@Range(min = 0, max = 5000)
	@ConfigItem(
		keyName = "fireRuneCostPerCast",
		name = "Fire Rune Cost Per Cast (GP)",
		description = "Total cost of the 5 Fire runes consumed per High Level Alchemy cast when not using a fire staff (e.g. 5 x 4 GP = 20 GP)",
		position = 4,
		section = costSection
	)
	default int fireRuneCostPerCast()
	{
		return 20;
	}

	// ==================== PRICING & MARKET SAFETY ====================

	@ConfigItem(
		keyName = "priceCalculationMethod",
		name = "Price Calculation Method",
		description = "Select which Grand Exchange market price metric is used as the estimated item purchase price",
		position = 10,
		section = pricingSection
	)
	default PriceCalculationMethod priceCalculationMethod()
	{
		return PriceCalculationMethod.INSTANT_BUY_HIGH;
	}

	@ConfigItem(
		keyName = "enableAutoRefresh",
		name = "Enable Automatic Refresh",
		description = "Automatically poll market data in the background at the configured refresh interval",
		position = 11,
		section = pricingSection
	)
	default boolean enableAutoRefresh()
	{
		return true;
	}

	@Range(min = 30, max = 900)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "refreshIntervalSeconds",
		name = "Refresh Interval",
		description = "Background market data refresh interval in seconds (minimum 30s to respect API rate limits)",
		position = 12,
		section = pricingSection
	)
	default int refreshIntervalSeconds()
	{
		return 60;
	}

	@Range(min = 5, max = 1440)
	@Units(Units.MINUTES)
	@ConfigItem(
		keyName = "maxDataAgeMinutes",
		name = "Maximum Data Age (Stale Threshold)",
		description = "Mark prices older than this threshold (in minutes) as STALE DATA and exclude them from confirmed recommendations",
		position = 13,
		section = pricingSection
	)
	default int maxDataAgeMinutes()
	{
		return 120;
	}

	// ==================== SCANNER DEFAULTS & FILTERS ====================

	@Range(min = -1000000, max = 10000000)
	@ConfigItem(
		keyName = "minimumProfit",
		name = "Minimum Profit (GP)",
		description = "Default minimum profit per alch in GP for scanner filtering",
		position = 20,
		section = scannerSection
	)
	default int minimumProfit()
	{
		return 1;
	}

	@Range(min = -100, max = 1000)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "minimumRoiPercent",
		name = "Minimum ROI (%)",
		description = "Default minimum Return on Investment percentage",
		position = 21,
		section = scannerSection
	)
	default int minimumRoiPercent()
	{
		return 0;
	}

	@Range(min = 0, max = 1000000)
	@ConfigItem(
		keyName = "minimumTradeVolume",
		name = "Minimum 1h Trade Volume",
		description = "Minimum 1-hour Grand Exchange trading volume required",
		position = 22,
		section = scannerSection
	)
	default int minimumTradeVolume()
	{
		return 0;
	}

	@Range(min = 0, max = 2147483647)
	@ConfigItem(
		keyName = "maximumPurchaseCost",
		name = "Maximum Item Purchase Cost (0 = No Max)",
		description = "Maximum unit purchase price in GP (set to 0 for no upper limit)",
		position = 23,
		section = scannerSection
	)
	default int maximumPurchaseCost()
	{
		return 0;
	}

	@Range(min = 1, max = 1000000)
	@ConfigItem(
		keyName = "defaultQuantity",
		name = "Default Quantity",
		description = "Default item quantity used for bulk profit calculations",
		position = 24,
		section = scannerSection
	)
	default int defaultQuantity()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "defaultSorting",
		name = "Default Sorting",
		description = "Default sorting criterion in the Live Alch Scanner",
		position = 25,
		section = scannerSection
	)
	default SortOption defaultSorting()
	{
		return SortOption.HIGHEST_PROFIT_PER_ALCH;
	}

	@ConfigItem(
		keyName = "showMembersItems",
		name = "Show Members Items",
		description = "Include Members-only (P2P) items in the scanner and dashboard",
		position = 26,
		section = scannerSection
	)
	default boolean showMembersItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showUnprofitableItems",
		name = "Show Unprofitable Items",
		description = "Include unprofitable (loss-making) items in the scanner when filters allow",
		position = 27,
		section = scannerSection
	)
	default boolean showUnprofitableItems()
	{
		return true;
	}

	// ==================== ALERTS & NOTIFICATIONS ====================

	@ConfigItem(
		keyName = "enableNotifications",
		name = "Enable Notifications",
		description = "Send RuneLite notifications when watchlist or scanner alert conditions are met",
		position = 30,
		section = alertSection
	)
	default boolean enableNotifications()
	{
		return true;
	}

	@Range(min = 0, max = 10000000)
	@ConfigItem(
		keyName = "alertProfitThresholdGp",
		name = "Alert When Profit Exceeds (GP)",
		description = "Trigger an alert when a watched item's net profit per alch exceeds this GP amount",
		position = 31,
		section = alertSection
	)
	default int alertProfitThresholdGp()
	{
		return 1000;
	}

	@Range(min = 0, max = 500)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "alertRoiThresholdPercent",
		name = "Alert When ROI Exceeds (%)",
		description = "Trigger an alert when a watched item's ROI exceeds this percentage",
		position = 32,
		section = alertSection
	)
	default int alertRoiThresholdPercent()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "alertOnBecomeProfitable",
		name = "Alert When Item Becomes Profitable",
		description = "Notify when a previously unprofitable watched item turns profitable",
		position = 33,
		section = alertSection
	)
	default boolean alertOnBecomeProfitable()
	{
		return true;
	}

	@Range(min = -1000000, max = 1000000)
	@ConfigItem(
		keyName = "alertProfitDropBelowGp",
		name = "Alert When Profit Drops Below (GP)",
		description = "Notify when a watched item's profit per alch drops below this GP floor",
		position = 34,
		section = alertSection
	)
	default int alertProfitDropBelowGp()
	{
		return 0;
	}

	@Range(min = 1, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "alertPriceChangePercent",
		name = "Alert on Significant Price Change (%)",
		description = "Notify when a watched item's purchase price moves by at least this percentage from baseline",
		position = 35,
		section = alertSection
	)
	default int alertPriceChangePercent()
	{
		return 10;
	}

	@Range(min = 1, max = 240)
	@Units(Units.MINUTES)
	@ConfigItem(
		keyName = "alertCooldownMinutes",
		name = "Alert Cooldown",
		description = "Minimum cooldown in minutes before repeating an identical alert for the same item",
		position = 36,
		section = alertSection
	)
	default int alertCooldownMinutes()
	{
		return 15;
	}
}

package com.alchmatepro;

import com.alchmatepro.AlchUiComponents.VerticalStackLayout;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingUtilities;
import lombok.Getter;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Root RuneLite panel for AlchMate Pro.
 * Hosts Section A (Brand Header), Section B (Primary & Secondary Navigation),
 * and the responsive scrollable viewport for all 7 application views.
 */
public class AlchMateProPanel extends PluginPanel implements NavigationController
{
	private final MarketDataService marketDataService;
	private final WatchlistService watchlistService;

	private final ActiveCardLayout cardLayout = new ActiveCardLayout();
	private final ScrollableCardContainer cardContainer = new ScrollableCardContainer(cardLayout);
	private final JScrollPane bodyScrollPane;
	private final Map<Section, JButton> navButtons = new EnumMap<>(Section.class);

	@Getter
	private final DashboardPanel dashboardPanel;
	@Getter
	private final AlchScannerPanel alchScannerPanel;
	@Getter
	private final ItemAnalysisPanel itemAnalysisPanel;
	@Getter
	private final ProfitCalculatorPanel profitCalculatorPanel;
	@Getter
	private final WatchlistPanel watchlistPanel;
	@Getter
	private final MarketDataPanel marketDataPanel;
	@Getter
	private final SettingsPanel settingsPanel;

	private Section activeSection = Section.DASHBOARD;

	@Inject
	public AlchMateProPanel(
		MarketDataService marketDataService,
		ProfitCalculator profitCalculator,
		RecommendationEngine recommendationEngine,
		PriceHistoryService priceHistoryService,
		WatchlistService watchlistService,
		AlertService alertService,
		CacheService cacheService,
		IconService iconService,
		AlchMateProConfig config,
		ConfigManager configManager)
	{
		super(false);
		this.marketDataService = marketDataService;
		this.watchlistService = watchlistService;

		setLayout(new BorderLayout(0, 0));
		setBackground(AlchTheme.BG_MAIN);
		setBorder(null);

		this.dashboardPanel = new DashboardPanel(marketDataService, recommendationEngine, iconService, this);
		this.alchScannerPanel = new AlchScannerPanel(marketDataService, watchlistService, iconService, config, this);
		this.itemAnalysisPanel = new ItemAnalysisPanel(
			marketDataService,
			profitCalculator,
			priceHistoryService,
			watchlistService,
			iconService,
			this
		);
		this.profitCalculatorPanel = new ProfitCalculatorPanel(marketDataService, profitCalculator, config);
		this.watchlistPanel = new WatchlistPanel(
			watchlistService,
			marketDataService,
			alertService,
			iconService,
			this
		);
		this.marketDataPanel = new MarketDataPanel(marketDataService, cacheService);
		this.settingsPanel = new SettingsPanel(config, configManager, marketDataService);

		cardContainer.setBackground(AlchTheme.BG_MAIN);
		cardContainer.add(dashboardPanel, Section.DASHBOARD.name());
		cardContainer.add(alchScannerPanel, Section.ALCH_SCANNER.name());
		cardContainer.add(itemAnalysisPanel, Section.ITEM_ANALYSIS.name());
		cardContainer.add(profitCalculatorPanel, Section.PROFIT_CALCULATOR.name());
		cardContainer.add(watchlistPanel, Section.WATCHLIST.name());
		cardContainer.add(marketDataPanel, Section.MARKET_DATA.name());
		cardContainer.add(settingsPanel, Section.SETTINGS.name());

		JPanel topChrome = new JPanel(new VerticalStackLayout(6));
		topChrome.setBackground(AlchTheme.BG_SECONDARY);
		topChrome.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, AlchTheme.BORDER_DEFAULT),
			BorderFactory.createEmptyBorder(AlchTheme.SPACE_SM, AlchTheme.SPACE_SM, AlchTheme.SPACE_SM, AlchTheme.SPACE_SM)
		));
		topChrome.add(buildBrandHeader());
		topChrome.add(buildNavigationGrid());

		this.bodyScrollPane = new JScrollPane(cardContainer);
		this.bodyScrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		this.bodyScrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
		AlchTheme.styleScrollPane(this.bodyScrollPane);

		add(topChrome, BorderLayout.NORTH);
		add(this.bodyScrollPane, BorderLayout.CENTER);

		this.marketDataService.addDataUpdateListener(this::refreshAllPanels);
		this.watchlistService.addChangeListener(watchlistPanel::refreshView);

		navigateTo(Section.DASHBOARD);
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(320, 760);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(235, 400);
	}

	private JPanel buildBrandHeader()
	{
		JPanel titles = new JPanel(new VerticalStackLayout(1));
		titles.setOpaque(false);

		JLabel mainTitle = new JLabel("WIZALCH");
		mainTitle.setFont(AlchTheme.getPageHeadingFont());
		mainTitle.setForeground(AlchTheme.ACCENT_GOLD);

		JLabel subTitle = new JLabel("HIGH ALCHEMY INTELLIGENCE");
		subTitle.setFont(AlchTheme.getSupportFont(true));
		subTitle.setForeground(AlchTheme.TEXT_SECONDARY);

		titles.add(mainTitle);
		titles.add(subTitle);

		JLabel versionBadge = AlchTheme.createBadge("v1.0", AlchTheme.ACCENT_GOLD, AlchTheme.ACCENT_GOLD_DIM);
		return AlchTheme.createSplitRow(titles, versionBadge);
	}

	private JPanel buildNavigationGrid()
	{
		JPanel navWrapper = new JPanel(new VerticalStackLayout(AlchTheme.SPACE_XS));
		navWrapper.setOpaque(false);

		JPanel primaryRow = new JPanel(new GridLayout(1, 4, AlchTheme.SPACE_XS, 0));
		primaryRow.setOpaque(false);

		JPanel secondaryRow = new JPanel(new GridLayout(1, 3, AlchTheme.SPACE_XS, 0));
		secondaryRow.setOpaque(false);

		Section[] sections = Section.values();
		for (int i = 0; i < sections.length; i++)
		{
			final Section sec = sections[i];
			JButton btn = createNavTabButton(sec);
			btn.addActionListener(e -> navigateTo(sec));
			navButtons.put(sec, btn);
			if (i < 4)
			{
				primaryRow.add(btn);
			}
			else
			{
				secondaryRow.add(btn);
			}
		}

		navWrapper.add(primaryRow);
		navWrapper.add(secondaryRow);
		return navWrapper;
	}

	private JButton createNavTabButton(Section section)
	{
		JButton btn = new JButton(section.getLabel());
		btn.setFont(AlchTheme.getBodyFont(true));
		btn.setFocusPainted(false);
		btn.setMargin(new Insets(2, 4, 2, 4));
		btn.setPreferredSize(new Dimension(56, 28));
		btn.setMinimumSize(new Dimension(48, 28));
		btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		btn.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (activeSection != section)
				{
					btn.setBackground(AlchTheme.BG_CARD_HOVER);
					btn.setForeground(AlchTheme.TEXT_PRIMARY);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (activeSection != section)
				{
					applyNavTabStyle(btn, false);
				}
			}
		});
		applyNavTabStyle(btn, false);
		return btn;
	}

	private void applyNavTabStyle(JButton btn, boolean active)
	{
		if (active)
		{
			btn.setBackground(AlchTheme.BG_CARD);
			btn.setForeground(AlchTheme.ACCENT_GOLD);
			btn.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(1, 1, 2, 1, AlchTheme.ACCENT_GOLD),
				BorderFactory.createEmptyBorder(3, 4, 2, 4)
			));
		}
		else
		{
			btn.setBackground(AlchTheme.BG_PANEL);
			btn.setForeground(AlchTheme.TEXT_SECONDARY);
			btn.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(AlchTheme.BORDER_DEFAULT, 1),
				BorderFactory.createEmptyBorder(3, 4, 3, 4)
			));
		}
	}

	@Override
	public void navigateTo(Section section)
	{
		if (section == null)
		{
			return;
		}
		this.activeSection = section;
		cardLayout.show(cardContainer, section.name());

		for (Map.Entry<Section, JButton> entry : navButtons.entrySet())
		{
			applyNavTabStyle(entry.getValue(), entry.getKey() == section);
		}

		refreshSection(section);
		cardContainer.revalidate();
		cardContainer.repaint();

		if (bodyScrollPane != null)
		{
			SwingUtilities.invokeLater(() -> bodyScrollPane.getVerticalScrollBar().setValue(0));
		}
	}

	@Override
	public void openItemAnalysis(AlchMateItem item)
	{
		itemAnalysisPanel.displayItem(item);
		navigateTo(Section.ITEM_ANALYSIS);
	}

	@Override
	public void openProfitCalculator(AlchMateItem item)
	{
		profitCalculatorPanel.loadItem(item);
		navigateTo(Section.PROFIT_CALCULATOR);
	}

	public void refreshAllPanels()
	{
		dashboardPanel.refreshView();
		alchScannerPanel.refreshView();
		itemAnalysisPanel.refreshCurrentItem();
		profitCalculatorPanel.syncDefaultsFromConfig();
		profitCalculatorPanel.recalculate();
		watchlistPanel.refreshView();
		marketDataPanel.refreshView();
		settingsPanel.loadFromConfig();
		cardContainer.revalidate();
		cardContainer.repaint();
	}

	private void refreshSection(Section section)
	{
		switch (section)
		{
			case DASHBOARD:
				dashboardPanel.refreshView();
				break;
			case ALCH_SCANNER:
				alchScannerPanel.refreshView();
				break;
			case ITEM_ANALYSIS:
				itemAnalysisPanel.refreshCurrentItem();
				break;
			case PROFIT_CALCULATOR:
				profitCalculatorPanel.recalculate();
				break;
			case WATCHLIST:
				watchlistPanel.refreshView();
				break;
			case MARKET_DATA:
				marketDataPanel.refreshView();
				break;
			case SETTINGS:
				settingsPanel.loadFromConfig();
				break;
		}
	}

	public Section getActiveSection()
	{
		return activeSection;
	}

	public void shutDown()
	{
		if (itemAnalysisPanel != null)
		{
			itemAnalysisPanel.shutDown();
		}
	}

	private static class ActiveCardLayout extends CardLayout
	{
		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			synchronized (parent.getTreeLock())
			{
				Insets insets = parent.getInsets();
				for (int i = 0; i < parent.getComponentCount(); i++)
				{
					Component c = parent.getComponent(i);
					if (c.isVisible())
					{
						if (parent.getWidth() > 0 && c.getWidth() != parent.getWidth() - insets.left - insets.right)
						{
							c.setSize(parent.getWidth() - insets.left - insets.right, c.getHeight());
						}
						Dimension d = c.getPreferredSize();
						return new Dimension(
							d.width + insets.left + insets.right,
							d.height + insets.top + insets.bottom
						);
					}
				}
				return super.preferredLayoutSize(parent);
			}
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			synchronized (parent.getTreeLock())
			{
				Insets insets = parent.getInsets();
				for (int i = 0; i < parent.getComponentCount(); i++)
				{
					Component c = parent.getComponent(i);
					if (c.isVisible())
					{
						Dimension d = c.getMinimumSize();
						return new Dimension(
							d.width + insets.left + insets.right,
							d.height + insets.top + insets.bottom
						);
					}
				}
				return super.minimumLayoutSize(parent);
			}
		}
	}

	private static class ScrollableCardContainer extends JPanel implements Scrollable
	{
		ScrollableCardContainer(CardLayout layout)
		{
			super(layout);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 20;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(60, visibleRect.height - 40);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.alchmatepro;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

/**
 * Main RuneLite Plugin entry point for AlchMate Pro.
 * Registers the sidebar NavigationButton, initialises background market polling,
 * and coordinates configuration updates without blocking the RuneLite client thread.
 */
@Slf4j
@PluginDescriptor(
	name = "WIZALCH",
	description = "Professional OSRS High Alchemy profit scanner, Grand Exchange price analyser, buy-limit calculator, watchlist, and smart recommendation engine",
	tags = {
		"wizalch",
		"alch",
		"alchemy",
		"high alch",
		"profit",
		"money making",
		"grand exchange",
		"ge",
		"margin",
		"calculator",
		"scanner",
		"magic"
	}
)
public class AlchMateProPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private AlchMateProConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private MarketDataService marketDataService;

	@Inject
	private ProfitCalculator profitCalculator;

	@Inject
	private RecommendationEngine recommendationEngine;

	@Inject
	private PriceHistoryService priceHistoryService;

	@Inject
	private WatchlistService watchlistService;

	@Inject
	private AlertService alertService;

	@Inject
	private CacheService cacheService;

	@Inject
	private IconService iconService;

	private AlchMateProPanel pluginPanel;
	private NavigationButton navButton;

	@Provides
	AlchMateProConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AlchMateProConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		log.info("Starting WIZALCH - High Alchemy Intelligence Plugin");

		pluginPanel = new AlchMateProPanel(
			marketDataService,
			profitCalculator,
			recommendationEngine,
			priceHistoryService,
			watchlistService,
			alertService,
			cacheService,
			iconService,
			config,
			configManager
		);

		BufferedImage icon = AlchTheme.createPluginToolbarIcon();

		navButton = NavigationButton.builder()
			.tooltip("WIZALCH - High Alch Profit Scanner")
			.icon(icon)
			.priority(5)
			.panel(pluginPanel)
			.build();

		clientToolbar.addNavigation(navButton);
		marketDataService.startUp();
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("Shutting down WIZALCH");
		if (navButton != null && clientToolbar != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (marketDataService != null)
		{
			marketDataService.shutDown();
		}
		if (pluginPanel != null)
		{
			pluginPanel.shutDown();
			pluginPanel = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event == null || !AlchMateProConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		// Ignore internal watchlist persistence writes so we don't loop
		if (AlchMateProConfig.WATCHLIST_DATA_KEY.equals(event.getKey()))
		{
			return;
		}

		marketDataService.syncSettingsFromConfig();

		if ("enableAutoRefresh".equals(event.getKey()) || "refreshIntervalSeconds".equals(event.getKey()))
		{
			marketDataService.rescheduleAutoRefresh();
		}

		marketDataService.recalculateAllItems();

		if (pluginPanel != null)
		{
			SwingUtilities.invokeLater(() -> pluginPanel.refreshAllPanels());
		}
	}
}

