				+ "\nOutdated information is never silently substituted as live.");
		}
		else
		{
			apiErrorArea.setForeground(AlchTheme.SUCCESS_GREEN);
			apiErrorArea.setText("✓ All bulk market endpoints operating normally. Zero API errors reported.");
		}
		revalidate();
		repaint();
	}
