package com.alchmatepro;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Singleton;
import lombok.Value;

/**
 * Validates Grand Exchange market prices, resolves purchase-side price estimates according
 * to the configured {@link PriceCalculationMethod}, checks data freshness, and flags
 * market safety risks such as low volume, instability, and potential price manipulation.
 */
@Singleton
public class PriceValidator
{
	@Value
	public static class ResolvedPurchasePrice
	{
		long priceGp;
		PriceSourceType sourceType;
		long ageSeconds;
		boolean stale;
		boolean valid;
	}

	/**
	 * Resolves the appropriate purchase-side price for an item based on the selected method
	 * and evaluates freshness against {@code maxDataAgeMinutes}.
	 */
	public ResolvedPurchasePrice resolvePurchasePrice(
		MarketPrice marketPrice,
		PriceCalculationMethod method,
		int maxDataAgeMinutes,
		long nowEpochSec)
	{
		if (marketPrice == null)
		{
			return new ResolvedPurchasePrice(0L, PriceSourceType.UNAVAILABLE, Long.MAX_VALUE, true, false);
		}

		PriceCalculationMethod effectiveMethod = method != null ? method : PriceCalculationMethod.INSTANT_BUY_HIGH;
		long resolvedPrice = 0L;
		PriceSourceType sourceType = PriceSourceType.UNAVAILABLE;

		switch (effectiveMethod)
		{
			case INSTANT_BUY_HIGH:
				if (isPositive(marketPrice.getInstantBuyPrice()))
				{
					resolvedPrice = marketPrice.getInstantBuyPrice();
					sourceType = PriceSourceType.INSTANT_BUY_PRICE;
				}
				else if (isPositive(marketPrice.getAvgHighPrice5m()))
				{
					resolvedPrice = marketPrice.getAvgHighPrice5m();
					sourceType = PriceSourceType.RECENT_5M_AVERAGE;
				}
				else if (isPositive(marketPrice.getAvgHighPrice1h()))
				{
					resolvedPrice = marketPrice.getAvgHighPrice1h();
					sourceType = PriceSourceType.STABLE_1H_AVERAGE;
				}
				else if (isPositive(marketPrice.getInstantSellPrice()))
				{
					resolvedPrice = marketPrice.getInstantSellPrice();
					sourceType = PriceSourceType.INSTANT_SELL_PRICE;
				}
				break;

			case STABLE_1H_HIGH:
				if (isPositive(marketPrice.getAvgHighPrice1h()))
				{
					resolvedPrice = marketPrice.getAvgHighPrice1h();
					sourceType = PriceSourceType.STABLE_1H_AVERAGE;
				}
				else if (isPositive(marketPrice.getAvgHighPrice5m()))
				{
					resolvedPrice = marketPrice.getAvgHighPrice5m();
					sourceType = PriceSourceType.RECENT_5M_AVERAGE;
				}
				else if (isPositive(marketPrice.getInstantBuyPrice()))
				{
					resolvedPrice = marketPrice.getInstantBuyPrice();
					sourceType = PriceSourceType.INSTANT_BUY_PRICE;
				}
				break;

			case ROLLING_5M_HIGH:
				if (isPositive(marketPrice.getAvgHighPrice5m()))
				{
					resolvedPrice = marketPrice.getAvgHighPrice5m();
					sourceType = PriceSourceType.RECENT_5M_AVERAGE;
				}
				else if (isPositive(marketPrice.getInstantBuyPrice()))
				{
					resolvedPrice = marketPrice.getInstantBuyPrice();
					sourceType = PriceSourceType.INSTANT_BUY_PRICE;
				}
				else if (isPositive(marketPrice.getAvgHighPrice1h()))
				{
					resolvedPrice = marketPrice.getAvgHighPrice1h();
					sourceType = PriceSourceType.STABLE_1H_AVERAGE;
				}
				break;

			case CONSERVATIVE_HIGH:
				long latestHigh = isPositive(marketPrice.getInstantBuyPrice()) ? marketPrice.getInstantBuyPrice() : 0L;
				long avg1hHigh = isPositive(marketPrice.getAvgHighPrice1h()) ? marketPrice.getAvgHighPrice1h() : 0L;
				long avg5mHigh = isPositive(marketPrice.getAvgHighPrice5m()) ? marketPrice.getAvgHighPrice5m() : 0L;
				resolvedPrice = Math.max(latestHigh, Math.max(avg1hHigh, avg5mHigh));
				if (resolvedPrice > 0)
				{
					sourceType = (latestHigh > 0 && avg1hHigh > 0)
						? PriceSourceType.CONSERVATIVE_ESTIMATE
						: (latestHigh > 0 ? PriceSourceType.INSTANT_BUY_PRICE : PriceSourceType.STABLE_1H_AVERAGE);
				}
				break;

			case PATIENT_OFFER_LOW:
				if (isPositive(marketPrice.getInstantSellPrice()))
				{
					resolvedPrice = marketPrice.getInstantSellPrice();
					sourceType = PriceSourceType.INSTANT_SELL_PRICE;
				}
				else if (isPositive(marketPrice.getAvgLowPrice1h()))
				{
					resolvedPrice = marketPrice.getAvgLowPrice1h();
					sourceType = PriceSourceType.STABLE_1H_AVERAGE;
				}
				else if (isPositive(marketPrice.getInstantBuyPrice()))
				{
					resolvedPrice = marketPrice.getInstantBuyPrice();
					sourceType = PriceSourceType.INSTANT_BUY_PRICE;
				}
				break;
		}

		if (resolvedPrice <= 0 && isPositive(marketPrice.getOfficialGePrice()))
		{
			resolvedPrice = marketPrice.getOfficialGePrice();
			sourceType = PriceSourceType.OFFICIAL_GE_GUIDE;
		}

		if (resolvedPrice <= 0)
		{
			return new ResolvedPurchasePrice(0L, PriceSourceType.UNAVAILABLE, Long.MAX_VALUE, true, false);
		}

		long tradeTime = marketPrice.getInstantBuyTimeEpochSec() != null && marketPrice.getInstantBuyTimeEpochSec() > 0
			? marketPrice.getInstantBuyTimeEpochSec()
			: marketPrice.getLatestTradeEpochSec();

		long ageSeconds = tradeTime > 0 && nowEpochSec >= tradeTime
			? (nowEpochSec - tradeTime)
			: (tradeTime > 0 ? 0L : Long.MAX_VALUE);

		long maxAgeSeconds = Math.max(60L, (long) maxDataAgeMinutes * 60L);
		boolean stale = (ageSeconds == Long.MAX_VALUE) || (ageSeconds > maxAgeSeconds);

		return new ResolvedPurchasePrice(resolvedPrice, sourceType, ageSeconds, stale, true);
	}

	/**
	 * Evaluates market safety warnings for an item given its metadata, pricing, and calculation.
	 */
	public List<MarketWarning> evaluateWarnings(
		ItemMetadata metadata,
		MarketPrice marketPrice,
		ResolvedPurchasePrice resolvedPrice,
		AlchCalculation calculation)
	{
		List<MarketWarning> warnings = new ArrayList<>();

		if (metadata == null || !metadata.isAlchable() || marketPrice == null
			|| resolvedPrice == null || !resolvedPrice.isValid()
			|| calculation == null || !calculation.isValid())
		{
			warnings.add(MarketWarning.INSUFFICIENT_DATA);
			return Collections.unmodifiableList(warnings);
		}

		if (resolvedPrice.isStale())
		{
			warnings.add(MarketWarning.STALE_DATA);
		}

		int vol1h = marketPrice.getTotalVolume1h();
		int vol5m = marketPrice.getTotalVolume5m();
		if (vol1h < 25 && vol5m < 5)
		{
			warnings.add(MarketWarning.LOW_VOLUME);
		}

		Integer instantHigh = marketPrice.getInstantBuyPrice();
		Integer avg1hHigh = marketPrice.getAvgHighPrice1h();
		if (isPositive(instantHigh) && isPositive(avg1hHigh))
		{
			double diffRatio = Math.abs((double) (instantHigh - avg1hHigh) / (double) avg1hHigh);
			if (diffRatio > 0.12)
			{
				warnings.add(MarketWarning.PRICE_UNSTABLE);
			}
			if (diffRatio > 0.28)
			{
				warnings.add(MarketWarning.POSSIBLE_PRICE_MANIPULATION);
			}
		}

		Double spreadPct = marketPrice.getSpreadPercent();
		if (spreadPct != null && Math.abs(spreadPct) > 30.0 && metadata.getHighAlchValue() >= 1000)
		{
			if (!warnings.contains(MarketWarning.POSSIBLE_PRICE_MANIPULATION))
			{
				warnings.add(MarketWarning.POSSIBLE_PRICE_MANIPULATION);
			}
		}

		if (calculation.getNetProfitPerAlch() > 5000 && vol1h < 15)
		{
			if (!warnings.contains(MarketWarning.POSSIBLE_PRICE_MANIPULATION))
			{
				warnings.add(MarketWarning.POSSIBLE_PRICE_MANIPULATION);
			}
		}

		if (resolvedPrice.getPriceGp() >= 250_000L
			|| (resolvedPrice.getPriceGp() >= 100_000L && calculation.getRoiPercent() < 1.5))
		{
			warnings.add(MarketWarning.HIGH_INVESTMENT);
		}

		return Collections.unmodifiableList(warnings);
	}

	private static boolean isPositive(Integer value)
	{
		return value != null && value > 0;
	}
}

package com.alchmatepro;

import javax.inject.Singleton;

/**
 * Dedicated financial calculation engine for Old School RuneScape High Level Alchemy.
 * Completely independent of UI components and uses 64-bit integer GP arithmetic
 * with overflow protection.
 *
 * Note: Grand Exchange tax is intentionally NOT applied because GE tax is paid by sellers,
 * and High Level Alchemy converts items directly into coins rather than selling on the GE.
 */
@Singleton
public class ProfitCalculator
{
	/**
	 * Calculates High Level Alchemy profit and return metrics using standard parameters
	 * (fire staff equipped = 0 fire rune cost, 0 additional cost, 0 buy limit).
	 */
	public AlchCalculation calculate(
		int itemId,
		long highAlchValue,
		long itemPurchaseCost,
		long natureRuneCost,
		int quantity)
	{
		return calculate(itemId, highAlchValue, itemPurchaseCost, natureRuneCost, 0L, 0L, quantity, 0, 0L);
	}

	/**
	 * Calculates High Level Alchemy profit and return metrics with fire rune cost and GE buy limit.
	 */
	public AlchCalculation calculate(
		int itemId,
		long highAlchValue,
		long itemPurchaseCost,
		long natureRuneCost,
		long fireRuneCostPerCast,
		int quantity,
		int geBuyLimit4h)
	{
		return calculate(
			itemId,
			highAlchValue,
			itemPurchaseCost,
			natureRuneCost,
			fireRuneCostPerCast,
			0L,
			quantity,
			geBuyLimit4h,
			0L
		);
	}

	/**
	 * Full High Level Alchemy calculation engine.
	 *
	 * @param itemId                  OSRS item ID
	 * @param highAlchValue           Coins generated per High Level Alchemy cast
	 * @param itemPurchaseCost        Estimated Grand Exchange unit purchase cost in GP
	 * @param natureRuneCost          Cost of 1 Nature rune in GP
	 * @param fireRuneCostPerCast     Cost of Fire runes per cast in GP (0 if fire staff equipped)
	 * @param otherCostPerCast        Any additional applicable cost per cast in GP
	 * @param quantity                Number of items to purchase and alch
	 * @param geBuyLimit4h            4-hour Grand Exchange buy limit (0 if unknown)
	 * @param targetMinProfitPerAlch  Target minimum profit per alch for max-affordable-price calculation
	 * @return Immutable {@link AlchCalculation} result
	 */
	public AlchCalculation calculate(
		int itemId,
		long highAlchValue,
		long itemPurchaseCost,
		long natureRuneCost,
		long fireRuneCostPerCast,
		long otherCostPerCast,
		int quantity,
		int geBuyLimit4h,
		long targetMinProfitPerAlch)
	{
		if (quantity <= 0)
		{
			return invalidResult(itemId, quantity, "Quantity must be greater than zero.");
		}
		if (highAlchValue <= 0)
		{
			return invalidResult(itemId, quantity, "High alchemy value must be positive.");
		}
		if (itemPurchaseCost <= 0)
		{
			return invalidResult(itemId, quantity, "Item purchase price is missing or invalid.");
		}
		if (natureRuneCost < 0 || fireRuneCostPerCast < 0 || otherCostPerCast < 0)
		{
			return invalidResult(itemId, quantity, "Rune and casting costs cannot be negative.");
		}

		long safeRuneAndOtherCost = safeAdd(safeAdd(natureRuneCost, fireRuneCostPerCast), otherCostPerCast);
		long totalCostPerAlch = safeAdd(itemPurchaseCost, safeRuneAndOtherCost);
		if (totalCostPerAlch <= 0)
		{
			return invalidResult(itemId, quantity, "Total cost per alch must be positive.");
		}

		long netProfitPerAlch = safeSubtract(highAlchValue, totalCostPerAlch);

		long grossAlchemyReturn = safeMultiply(highAlchValue, quantity);
		long totalPurchaseCost = safeMultiply(itemPurchaseCost, quantity);
		long totalNatureRuneExp = safeMultiply(natureRuneCost, quantity);
		long totalFireRuneExp = safeMultiply(fireRuneCostPerCast, quantity);
		long totalOtherExp = safeMultiply(otherCostPerCast, quantity);
		long totalInvestment = safeMultiply(totalCostPerAlch, quantity);
		long totalNetProfit = safeMultiply(netProfitPerAlch, quantity);

		double roiPercent = ((double) netProfitPerAlch / (double) totalCostPerAlch) * 100.0;
		double totalReturnRatioPercent = ((double) grossAlchemyReturn / (double) totalInvestment) * 100.0;

		long breakEvenPurchasePrice = Math.max(0L, safeSubtract(highAlchValue, safeRuneAndOtherCost));
		long maxAffordablePurchasePrice = Math.max(
			0L,
			safeSubtract(breakEvenPurchasePrice, Math.max(0L, targetMinProfitPerAlch))
		);

		int safeBuyLimit = Math.max(0, geBuyLimit4h);
		long maxBuyLimitInvestment = safeBuyLimit > 0 ? safeMultiply(totalCostPerAlch, safeBuyLimit) : 0L;
		long maxBuyLimitProfit4h = safeBuyLimit > 0 ? safeMultiply(netProfitPerAlch, safeBuyLimit) : 0L;

		long profitPer100 = safeMultiply(netProfitPerAlch, 100L);
		long profitPer1000 = safeMultiply(netProfitPerAlch, 1000L);

		return AlchCalculation.builder()
			.itemId(itemId)
			.quantity(quantity)
			.highAlchValuePerItem(highAlchValue)
			.purchaseCostPerItem(itemPurchaseCost)
			.natureRuneCostPerCast(natureRuneCost)
			.fireRuneCostPerCast(fireRuneCostPerCast)
			.otherCostPerCast(otherCostPerCast)
			.totalCostPerAlch(totalCostPerAlch)
			.netProfitPerAlch(netProfitPerAlch)
			.grossAlchemyReturn(grossAlchemyReturn)
			.totalPurchaseCost(totalPurchaseCost)
			.totalNatureRuneExpenditure(totalNatureRuneExp)
			.totalFireRuneExpenditure(totalFireRuneExp)
			.totalOtherExpenditure(totalOtherExp)
			.totalInvestment(totalInvestment)
			.totalNetProfit(totalNetProfit)
			.roiPercent(roiPercent)
			.totalReturnRatioPercent(totalReturnRatioPercent)
			.breakEvenPurchasePrice(breakEvenPurchasePrice)
			.maxAffordablePurchasePrice(maxAffordablePurchasePrice)
			.geBuyLimit4h(safeBuyLimit)
			.maxBuyLimitInvestment(maxBuyLimitInvestment)
			.maxBuyLimitProfit4h(maxBuyLimitProfit4h)
			.maxBuyLimitNatureRunes(safeBuyLimit)
			.profitPer100Alchs(profitPer100)
			.profitPer1000Alchs(profitPer1000)
			.valid(true)
			.validationMessage("OK")
			.build();
	}

	/**
	 * Calculates the maximum unit purchase price a player can afford given a total capital budget
	 * and desired quantity, factoring in rune expenditure per cast.
	 */
	public long calculateMaxAffordableUnitPriceFromBudget(
		long totalBudgetGp,
		int quantity,
		long natureRuneCost,
		long fireRuneCostPerCast,
		long otherCostPerCast)
	{
		if (totalBudgetGp <= 0 || quantity <= 0)
		{
			return 0L;
		}
		long maxCostPerCast = totalBudgetGp / quantity;
		long runeOverhead = safeAdd(safeAdd(Math.max(0L, natureRuneCost), Math.max(0L, fireRuneCostPerCast)), Math.max(0L, otherCostPerCast));
		return Math.max(0L, maxCostPerCast - runeOverhead);
	}

	private AlchCalculation invalidResult(int itemId, int quantity, String reason)
	{
		return AlchCalculation.builder()
			.itemId(itemId)
			.quantity(Math.max(0, quantity))
			.valid(false)
			.validationMessage(reason)
			.build();
	}

	public static long safeAdd(long a, long b)
	{
		try
		{
			return Math.addExact(a, b);
		}
		catch (ArithmeticException ex)
		{
			return (a > 0 && b > 0) ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	public static long safeSubtract(long a, long b)
	{
		try
		{
			return Math.subtractExact(a, b);
		}
		catch (ArithmeticException ex)
		{
			return (a > 0 && b < 0) ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	public static long safeMultiply(long a, long b)
	{
		try
		{
			return Math.multiplyExact(a, b);
		}
		catch (ArithmeticException ex)
		{
			boolean positive = (a >= 0 && b >= 0) || (a < 0 && b < 0);
			return positive ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}
}

