}

package com.alchmatepro;

import com.alchmatepro.AlchUiComponents.ResponsiveGridLayout;
import com.alchmatepro.AlchUiComponents.VerticalStackLayout;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.util.List;
import java.util.Optional;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JTextArea;
import javax.swing.SpinnerNumberModel;

/**
 * Persistent Personal Watchlist and Profit Alert Monitor panel (Sections 12 & 13).
 * Allows users to track favourite items, configure target profit & minimum ROI,
 * compare current prices against baseline, toggle alerts, and view recent alert history.
 */
public class WatchlistPanel extends JPanel
{
	private final WatchlistService watchlistService;
	private final MarketDataService marketDataService;
	private final AlertService alertService;
	private final IconService iconService;
	private final NavigationController navigationController;

	private final JLabel countSummaryLabel = new JLabel("0 watched items");
	private final JPanel watchlistItemsContainer = new JPanel(new VerticalStackLayout(AlchTheme.SPACE_SM));
	private final JPanel alertsHistoryContainer = new JPanel(new VerticalStackLayout(AlchTheme.SPACE_XS));

	public WatchlistPanel(
		WatchlistService watchlistService,
		MarketDataService marketDataService,
		AlertService alertService,
		IconService iconService,
		NavigationController navigationController)
	{
		super(new VerticalStackLayout(AlchTheme.SPACE_SM));
		this.watchlistService = watchlistService;
		this.marketDataService = marketDataService;
		this.alertService = alertService;
		this.iconService = iconService;
		this.navigationController = navigationController;

		setBackground(AlchTheme.BG_MAIN);
		setBorder(BorderFactory.createEmptyBorder(
			AlchTheme.SPACE_SM, AlchTheme.SPACE_SM, AlchTheme.SPACE_MD, AlchTheme.SPACE_SM
		));

		add(buildHeaderCard());
		add(buildWatchlistSection());
		add(buildAlertHistorySection());
	}

	private JPanel buildHeaderCard()
	{
		JPanel card = new JPanel(new VerticalStackLayout(AlchTheme.SPACE_XS));
		card.setBackground(AlchTheme.BG_CARD);
		card.setBorder(AlchTheme.createGoldCardBorder());

		JLabel title = AlchTheme.createSectionHeading("PERSONAL WATCHLIST & ALERTS");

		JButton clearAllBtn = AlchTheme.createDangerButton("Clear All");
		clearAllBtn.setToolTipText("Remove all items from your watchlist (requires confirmation)");
		clearAllBtn.addActionListener(e -> confirmAndClearWatchlist());

		countSummaryLabel.setFont(AlchTheme.getBodyFont(false));
		countSummaryLabel.setForeground(AlchTheme.TEXT_SECONDARY);

		card.add(AlchTheme.createSplitRow(title, clearAllBtn));
		card.add(countSummaryLabel);
		return card;
	}

	private JPanel buildWatchlistSection()
	{
		watchlistItemsContainer.setOpaque(false);
		return watchlistItemsContainer;
	}

	private JPanel buildAlertHistorySection()
	{
		JPanel wrapper = new JPanel(new VerticalStackLayout(AlchTheme.SPACE_SM));
		wrapper.setBackground(AlchTheme.BG_CARD);
		wrapper.setBorder(AlchTheme.createCardBorder());

		JLabel title = AlchTheme.createSectionHeading("RECENT PROFIT ALERTS");

		JButton clearAlertsBtn = AlchTheme.createSecondaryButton("Clear Log");
		clearAlertsBtn.addActionListener(e -> {
			alertService.clearAlertHistory();
			refreshView();
		});

		alertsHistoryContainer.setOpaque(false);

		wrapper.add(AlchTheme.createSplitRow(title, clearAlertsBtn));
		wrapper.add(alertsHistoryContainer);
		return wrapper;
	}

	private void confirmAndClearWatchlist()
	{
		if (watchlistService.size() == 0)
		{
			return;
		}
		int result = JOptionPane.showConfirmDialog(
			this,
			"Are you sure you want to remove all " + watchlistService.size() + " items from your Watchlist?",
			"Confirm Clear Watchlist",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE
		);
		if (result == JOptionPane.YES_OPTION)
		{
			watchlistService.clearAll();
			refreshView();
		}
	}

	public void refreshView()
	{
		List<WatchlistEntry> entries = watchlistService.getAllEntries();
		countSummaryLabel.setText(entries.size() + " watched item" + (entries.size() == 1 ? "" : "s")
			+ " (persisted across sessions)");

		watchlistItemsContainer.removeAll();
		if (entries.isEmpty())
		{
			JPanel emptyCard = new JPanel(new VerticalStackLayout(AlchTheme.SPACE_SM));
			emptyCard.setBackground(AlchTheme.BG_CARD);
			emptyCard.setBorder(AlchTheme.createSpaciousCardBorder());

			JLabel emptyTitle = new JLabel("Your Watchlist is Empty");
			emptyTitle.setFont(AlchTheme.getSectionHeadingFont());
			emptyTitle.setForeground(AlchTheme.TEXT_PRIMARY);

			JTextArea emptySub = AlchUiComponents.createReadOnlyTextArea(
				"Click '☆ Watch' on any item in the Live Alch Scanner or Item Analysis page to track price movements and receive automatic profit alerts.",
				AlchTheme.TEXT_SECONDARY
			);

			emptyCard.add(emptyTitle);
			emptyCard.add(emptySub);
			watchlistItemsContainer.add(emptyCard);
		}
		else
		{
			for (WatchlistEntry entry : entries)
			{
				watchlistItemsContainer.add(buildWatchlistEntryCard(entry));
			}
		}

		// Recent alerts log
		alertsHistoryContainer.removeAll();
		List<AlertEvent> alerts = alertService.getRecentAlerts();
		if (alerts.isEmpty())
		{
			JLabel noAlertsLbl = new JLabel("No alerts triggered yet in this session.");
			noAlertsLbl.setFont(AlchTheme.getBodyFont(false));
			noAlertsLbl.setForeground(AlchTheme.TEXT_MUTED);
			alertsHistoryContainer.add(noAlertsLbl);
		}
		else
		{
			int shown = Math.min(8, alerts.size());
			for (int i = 0; i < shown; i++)
			{
				AlertEvent ev = alerts.get(i);
				String text = String.format(
					"[%s] %s",
					AlchTheme.formatEpochTimestamp(ev.getTriggeredAtEpochSec()),
					ev.getMessage().replace("[WIZALCH] ", "").replace("[AlchMate Pro] ", "")
				);
				JTextArea alertArea = AlchUiComponents.createReadOnlyTextArea(text, AlchTheme.ACCENT_GOLD);
				alertArea.setBackground(AlchTheme.BG_PANEL);
				alertArea.setOpaque(true);
				alertArea.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
				alertsHistoryContainer.add(alertArea);
			}
		}

		revalidate();
		repaint();
	}

	private JPanel buildWatchlistEntryCard(WatchlistEntry entry)
	{
		JPanel card = new JPanel(new VerticalStackLayout(AlchTheme.SPACE_SM));
		card.setBackground(AlchTheme.BG_CARD);
		card.setBorder(entry.isFavourite() ? AlchTheme.createGoldCardBorder() : AlchTheme.createCardBorder());

		Optional<AlchMateItem> liveItemOpt = marketDataService.getItemById(entry.getItemId());
		AlchMateItem liveItem = liveItemOpt.orElse(null);

		// Header row: Icon + Name (Left) | Favourite + Remove (Right)
		JPanel leftHeader = new JPanel(new GridBagLayout());
		leftHeader.setOpaque(false);

		JLabel iconLbl = new JLabel();
		iconService.attachItemIcon(iconLbl, entry.getItemId(), entry.getItemName());

		JLabel nameLbl = new JLabel((entry.isFavourite() ? "★ " : "") + entry.getItemName());
		nameLbl.setFont(AlchTheme.getSectionHeadingFont());
		nameLbl.setForeground(entry.isFavourite() ? AlchTheme.ACCENT_GOLD : AlchTheme.TEXT_PRIMARY);

		GridBagConstraints gbcIcon = new GridBagConstraints();
		gbcIcon.gridx = 0;
		gbcIcon.gridy = 0;
		gbcIcon.insets = new Insets(0, 0, 0, AlchTheme.SPACE_SM);
		gbcIcon.anchor = GridBagConstraints.WEST;
		leftHeader.add(iconLbl, gbcIcon);

		GridBagConstraints gbcName = new GridBagConstraints();
		gbcName.gridx = 1;
		gbcName.gridy = 0;
		gbcName.weightx = 1.0;
		gbcName.fill = GridBagConstraints.HORIZONTAL;
		gbcName.anchor = GridBagConstraints.WEST;
		leftHeader.add(nameLbl, gbcName);

		JPanel topBtns = new JPanel(new FlowLayout(FlowLayout.RIGHT, AlchTheme.SPACE_XS, 0));
		topBtns.setOpaque(false);

		JButton favBtn = AlchTheme.createSecondaryButton(entry.isFavourite() ? "★ Fav" : "☆ Fav");
		if (entry.isFavourite())
		{
			favBtn.setForeground(AlchTheme.ACCENT_GOLD);
		}
		favBtn.setToolTipText("Toggle favourite status");
		favBtn.addActionListener(e -> watchlistService.toggleFavourite(entry.getItemId()));

		JButton removeBtn = AlchTheme.createDangerButton("Remove");
		removeBtn.setToolTipText("Remove from watchlist");
		removeBtn.addActionListener(e -> watchlistService.removeItem(entry.getItemId()));

		topBtns.add(favBtn);
		topBtns.add(removeBtn);

		card.add(AlchTheme.createSplitRow(leftHeader, topBtns));

		// Live Price & Delta Comparison Rows
		JPanel metricsRows = new JPanel(new VerticalStackLayout(2));
		metricsRows.setOpaque(false);

		if (liveItem != null && liveItem.hasValidPrice())
		{
			long currentBuy = liveItem.getEstimatedPurchasePrice();
			long baseBuy = entry.getBaselinePurchasePrice();
			long priceDiff = baseBuy > 0 ? (currentBuy - baseBuy) : 0L;

			long currentProfit = liveItem.getNetProfitPerAlch();
			long baseProfit = entry.getBaselineProfitPerAlch();
			long profitDiff = currentProfit - baseProfit;

			JLabel curBuyLbl = new JLabel(AlchTheme.formatGp(currentBuy));
			curBuyLbl.setForeground(AlchTheme.TEXT_PRIMARY);

			JLabel curProfitLbl = new JLabel(AlchTheme.formatSignedGp(currentProfit)
				+ " (" + AlchTheme.formatRoi(liveItem.getRoiPercent()) + ")");
			curProfitLbl.setForeground(AlchTheme.getProfitColor(currentProfit));

			JLabel priceDiffLbl = new JLabel(AlchTheme.formatSignedGp(priceDiff));
			priceDiffLbl.setForeground(priceDiff <= 0 ? AlchTheme.SUCCESS_GREEN : AlchTheme.DANGER_RED);

			JLabel profitDiffLbl = new JLabel(AlchTheme.formatSignedGp(profitDiff));
			profitDiffLbl.setForeground(AlchTheme.getProfitColor(profitDiff));

			metricsRows.add(AlchTheme.createKeyValueRow("Current Buy Price", curBuyLbl, true));
			metricsRows.add(AlchTheme.createKeyValueRow("Current Net Profit", curProfitLbl, false));
			metricsRows.add(AlchTheme.createKeyValueRow("Buy Price vs Baseline", priceDiffLbl, true));
			metricsRows.add(AlchTheme.createKeyValueRow("Profit Change vs Baseline", profitDiffLbl, false));
		}
		else
		{
			JLabel baseLbl = new JLabel(AlchTheme.formatGp(entry.getBaselinePurchasePrice()));
			baseLbl.setForeground(AlchTheme.TEXT_MUTED);
			JLabel statusLbl = new JLabel("Awaiting market sync...");
			statusLbl.setForeground(AlchTheme.ACCENT_GOLD);

			metricsRows.add(AlchTheme.createKeyValueRow("Baseline Buy Price", baseLbl, true));
			metricsRows.add(AlchTheme.createKeyValueRow("Live Status", statusLbl, false));
		}
		card.add(metricsRows);

		// Target Profit & Min ROI Editors
		JSpinner targetProfitSpinner = new JSpinner(new SpinnerNumberModel(entry.getTargetProfitGp(), -100000, 10000000, 50));
		AlchTheme.styleSpinner(targetProfitSpinner);

		JSpinner minRoiSpinner = new JSpinner(new SpinnerNumberModel(entry.getMinimumRoiPercent(), 0.0, 500.0, 0.5));
		AlchTheme.styleSpinner(minRoiSpinner);

		card.add(AlchTheme.createFormControlRow("Target Alert Profit (GP)", targetProfitSpinner));
		card.add(AlchTheme.createFormControlRow("Minimum Alert ROI (%)", minRoiSpinner));

		// Bottom Action Bar
		JCheckBox alertCheck = new JCheckBox("Alerts Enabled", entry.isAlertEnabled());
		AlchTheme.styleCheckBox(alertCheck);
		alertCheck.addActionListener(e -> watchlistService.toggleAlertEnabled(entry.getItemId()));

		JPanel actionBtns = new JPanel(new ResponsiveGridLayout(90, 2, AlchTheme.SPACE_XS, AlchTheme.SPACE_XS));
		actionBtns.setOpaque(false);

		JButton saveTargetBtn = AlchTheme.createSecondaryButton("Save Target");
		saveTargetBtn.addActionListener(e -> {
			int tp = ((Number) targetProfitSpinner.getValue()).intValue();
			double mr = ((Number) minRoiSpinner.getValue()).doubleValue();
			watchlistService.updateTargets(entry.getItemId(), tp, mr);
		});

		JButton inspectBtn = AlchTheme.createPrimaryButton("Inspect Item");
		inspectBtn.setEnabled(liveItem != null);
		inspectBtn.addActionListener(e -> {
			if (liveItem != null)
			{
				navigationController.openItemAnalysis(liveItem);
			}
		});

		actionBtns.add(saveTargetBtn);
		actionBtns.add(inspectBtn);

		card.add(alertCheck);
		card.add(actionBtns);
		return card;
	}
}

package com.alchmatepro;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Manages the user's persistent personal watchlist (Section 12).
 * Persists watchlist entries across game restarts using RuneLite's {@link ConfigManager}.
 */
@Slf4j
@Singleton
public class WatchlistService
{
	private final ConfigManager configManager;
	private final Gson gson;

	private final Map<Integer, WatchlistEntry> entries = new LinkedHashMap<>();
	private final List<Runnable> changeListeners = new CopyOnWriteArrayList<>();

	@Inject
	public WatchlistService(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		loadFromConfig();
	}

	public synchronized void loadFromConfig()
	{
		entries.clear();
		if (configManager == null)
		{
			return;
		}
		try
		{
			String rawJson = configManager.getConfiguration(
				AlchMateProConfig.CONFIG_GROUP,
				AlchMateProConfig.WATCHLIST_DATA_KEY
			);
			if (rawJson == null || rawJson.trim().isEmpty())
			{
				return;
			}

			Type listType = new TypeToken<List<WatchlistEntry>>()
			{
			}.getType();
			List<WatchlistEntry> loaded = gson.fromJson(rawJson, listType);
			if (loaded != null)
			{
				for (WatchlistEntry entry : loaded)
				{
					if (entry != null && entry.getItemId() > 0)
					{
						entries.put(entry.getItemId(), entry);
					}
				}
			}
		}
		catch (Exception ex)
		{
			log.warn("Failed to load watchlist configuration, starting with empty watchlist: {}", ex.getMessage());
		}
	}

	public synchronized void saveToConfig()
	{
		if (configManager == null)
		{
			return;
		}
		try
		{
			List<WatchlistEntry> list = new ArrayList<>(entries.values());
			String json = gson.toJson(list);
			configManager.setConfiguration(
				AlchMateProConfig.CONFIG_GROUP,
				AlchMateProConfig.WATCHLIST_DATA_KEY,
				json
			);
		}
		catch (Exception ex)
		{
			log.warn("Failed to persist watchlist to ConfigManager: {}", ex.getMessage());
		}
	}

	public synchronized WatchlistEntry addOrUpdateItem(
		AlchMateItem item,
		int targetProfitGp,
		double minimumRoiPercent)
	{
		if (item == null || item.getId() <= 0)
		{
			return null;
		}
		int itemId = item.getId();
		WatchlistEntry existing = entries.get(itemId);
		long now = Instant.now().getEpochSecond();

		WatchlistEntry updated = WatchlistEntry.builder()
			.itemId(itemId)
			.itemName(item.getName())
			.addedEpochSec(existing != null ? existing.getAddedEpochSec() : now)
			.favourite(existing != null && existing.isFavourite())
			.targetProfitGp(targetProfitGp)
			.minimumRoiPercent(minimumRoiPercent)
			.baselinePurchasePrice(existing != null && existing.getBaselinePurchasePrice() > 0
				? existing.getBaselinePurchasePrice()
				: item.getEstimatedPurchasePrice())
			.baselineProfitPerAlch(existing != null
				? existing.getBaselineProfitPerAlch()
				: item.getNetProfitPerAlch())
			.alertEnabled(existing == null || existing.isAlertEnabled())
			.build();

		entries.put(itemId, updated);
		saveToConfig();
		notifyListeners();
		return updated;
	}

	public synchronized void addItem(AlchMateItem item)
	{
		if (item == null || item.getId() <= 0)
		{
			return;
		}
		int defaultTargetProfit = Math.max(250, (int) Math.max(0L, item.getNetProfitPerAlch()));
		double defaultMinRoi = Math.max(1.0, Math.round(Math.max(0.0, item.getRoiPercent()) * 10.0) / 10.0);
		addOrUpdateItem(item, defaultTargetProfit, defaultMinRoi);
	}

	public synchronized boolean removeItem(int itemId)
	{
		WatchlistEntry removed = entries.remove(itemId);
		if (removed != null)
		{
			saveToConfig();
			notifyListeners();
			return true;
		}
		return false;
	}

	public synchronized void toggleItem(AlchMateItem item)
	{
		if (item == null)
		{
			return;
		}
		if (isWatched(item.getId()))
		{
			removeItem(item.getId());
		}
		else
		{
			addItem(item);
		}
	}

	public synchronized void toggleFavourite(int itemId)
	{
		WatchlistEntry entry = entries.get(itemId);
		if (entry != null)
		{
			entry.setFavourite(!entry.isFavourite());
			saveToConfig();
			notifyListeners();
		}
	}

	public synchronized void toggleAlertEnabled(int itemId)
	{
		WatchlistEntry entry = entries.get(itemId);
		if (entry != null)
		{
			entry.setAlertEnabled(!entry.isAlertEnabled());
			saveToConfig();
			notifyListeners();
		}
	}

	public synchronized void updateTargets(int itemId, int targetProfitGp, double minimumRoiPercent)
	{
		WatchlistEntry entry = entries.get(itemId);
		if (entry != null)
		{
			entry.setTargetProfitGp(targetProfitGp);
			entry.setMinimumRoiPercent(minimumRoiPercent);
			saveToConfig();
			notifyListeners();
		}
	}

	public synchronized void resetBaseline(AlchMateItem currentItem)
	{
		if (currentItem == null)
		{
			return;
		}
		WatchlistEntry entry = entries.get(currentItem.getId());
		if (entry != null)
		{
			entry.setBaselinePurchasePrice(currentItem.getEstimatedPurchasePrice());
			entry.setBaselineProfitPerAlch(currentItem.getNetProfitPerAlch());
			saveToConfig();
			notifyListeners();
		}
	}

	public synchronized void clearAll()
	{
		entries.clear();
		saveToConfig();
		notifyListeners();
	}

	public synchronized boolean isWatched(int itemId)
	{
		return entries.containsKey(itemId);
	}

	public synchronized WatchlistEntry getEntry(int itemId)
	{
		return entries.get(itemId);
	}

	public synchronized int size()
	{
		return entries.size();
	}

	/**
	 * Returns all watchlist entries sorted with favourites first, then by added time descending.
	 */
	public synchronized List<WatchlistEntry> getAllEntries()
	{
		List<WatchlistEntry> list = new ArrayList<>(entries.values());
		list.sort(
			Comparator.comparing(WatchlistEntry::isFavourite).reversed()
				.thenComparing(Comparator.comparingLong(WatchlistEntry::getAddedEpochSec).reversed())
		);
		return list;
	}

	public void addChangeListener(Runnable listener)
	{
		if (listener != null)
		{
			changeListeners.add(listener);
		}
	}

	private void notifyListeners()
	{
		for (Runnable listener : changeListeners)
		{
			try
			{
				listener.run();
			}
			catch (Exception ex)
			{
				log.debug("Watchlist listener error: {}", ex.getMessage());
			}
		}
	}
}

package com.alchmatepro;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Official OSRS Wiki Real-Time Prices API provider (https://prices.runescape.wiki/api/v1/osrs).
 * Retrieves bulk pricing and volume telemetry from /latest, /5m, and /1h endpoints
 * with timeouts, retry backoff, rate limiting, and strict JSON validation.
 */
@Slf4j
@Singleton
public class WikiPriceDataProvider implements MarketDataProvider
{
	public static final String DEFAULT_BASE_URL = "https://prices.runescape.wiki/api/v1/osrs";
	public static final String USER_AGENT = "WIZALCH-RuneLite-Plugin/1.0 (+https://github.com/WizardOfAus666/wizalch)";

	private static final int MAX_RETRIES = 2;
	private static final long INITIAL_BACKOFF_MS = 400L;
	private static final long MIN_REQUEST_INTERVAL_MS = 5_000L;

	private final OkHttpClient httpClient;
	private final Gson gson;

	@Getter
	@Setter
	private volatile String baseUrl = DEFAULT_BASE_URL;

	private volatile boolean available = true;
	private volatile String statusSummary = "Ready (OSRS Wiki Real-Time Prices API v1)";
	private volatile long lastRequestTimeMs = 0L;

	@Inject
	public WikiPriceDataProvider(OkHttpClient okHttpClient, Gson gson)
	{
		this.httpClient = okHttpClient;
		this.gson = gson;
	}

	@Override
	public String getProviderName()
	{
		return "OSRS Wiki Real-Time Prices API";
	}

	@Override
	public boolean isAvailable()
	{
		return available;
	}

	@Override
	public String getStatusSummary()
	{
		return statusSummary;
	}

	@Override
	public synchronized Map<Integer, MarketPrice> fetchMarketPrices() throws IOException
	{
		long nowMs = System.currentTimeMillis();
		long elapsedMs = nowMs - lastRequestTimeMs;
		if (lastRequestTimeMs > 0 && elapsedMs < MIN_REQUEST_INTERVAL_MS)
		{
			throw new IOException("Rate-limit guard: request interval below minimum threshold.");
		}
		lastRequestTimeMs = nowMs;

		long fetchedAtEpochSec = Instant.now().getEpochSecond();

		try
		{
			String latestJson = executeWithRetry(baseUrl + "/latest");
			Map<Integer, MarketPrice> priceMap = parseLatestJson(latestJson, fetchedAtEpochSec);

			if (priceMap.isEmpty())
			{
				available = false;
				statusSummary = "OSRS Wiki /latest returned 0 valid prices.";
				throw new IOException(statusSummary);
			}

			// Enrich with /5m rolling averages and volume (non-fatal if /5m fails)
			try
			{
				String fiveMinJson = executeWithRetry(baseUrl + "/5m");
				merge5mJson(priceMap, fiveMinJson, fetchedAtEpochSec);
			}
			catch (Exception ex)
			{
				log.debug("Non-fatal: failed to merge /5m prices: {}", ex.getMessage());
			}

			// Enrich with /1h stable averages and volume (non-fatal if /1h fails)
			try
			{
				String oneHourJson = executeWithRetry(baseUrl + "/1h");
				merge1hJson(priceMap, oneHourJson, fetchedAtEpochSec);
			}
			catch (Exception ex)
			{
				log.debug("Non-fatal: failed to merge /1h prices: {}", ex.getMessage());
			}

			available = true;
			statusSummary = "Connected (" + priceMap.size() + " live items via /latest, /5m, /1h)";
			return priceMap;
		}
		catch (IOException ex)
		{
			available = false;
			statusSummary = "Wiki API error: " + ex.getMessage();
			throw ex;
		}
	}

	/**
	 * Parses the /latest JSON response into a map of itemId -> {@link MarketPrice}.
	 */
	public Map<Integer, MarketPrice> parseLatestJson(String json, long fetchedAtEpochSec) throws IOException
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new IOException("Empty JSON payload from /latest endpoint.");
		}

		try
		{
			JsonElement rootElement = gson.fromJson(json, JsonElement.class);
			if (rootElement == null || !rootElement.isJsonObject())
			{
				throw new IOException("Malformed /latest JSON root object.");
			}

			JsonObject root = rootElement.getAsJsonObject();
			if (!root.has("data") || !root.get("data").isJsonObject())
			{
				throw new IOException("Missing 'data' object in /latest JSON response.");
			}

			JsonObject data = root.getAsJsonObject("data");
			Map<Integer, MarketPrice> result = new HashMap<>(data.size());

			for (Map.Entry<String, JsonElement> entry : data.entrySet())
			{
				int itemId;
				try
				{
					itemId = Integer.parseInt(entry.getKey());
				}
				catch (NumberFormatException ignored)
				{
					continue;
				}
				if (itemId <= 0 || !entry.getValue().isJsonObject())
				{
					continue;
				}

				JsonObject itemObj = entry.getValue().getAsJsonObject();
				Integer high = getPositiveInt(itemObj, "high");
				Long highTime = getPositiveLong(itemObj, "highTime");
				Integer low = getPositiveInt(itemObj, "low");
				Long lowTime = getPositiveLong(itemObj, "lowTime");

				if (high == null && low == null)
				{
					continue;
				}

				MarketPrice mp = MarketPrice.builder()
					.itemId(itemId)
					.instantBuyPrice(high)
					.instantBuyTimeEpochSec(highTime)
					.instantSellPrice(low)
					.instantSellTimeEpochSec(lowTime)
					.fetchedAtEpochSec(fetchedAtEpochSec)
					.build();

				result.put(itemId, mp);
			}

			return result;
		}
		catch (JsonSyntaxException ex)
		{
			throw new IOException("Invalid JSON syntax from /latest endpoint: " + ex.getMessage(), ex);
		}
	}

	/**
	 * Merges /5m rolling average pricing and volumes into the existing price map.
	 */
	public void merge5mJson(Map<Integer, MarketPrice> priceMap, String json, long fetchedAtEpochSec) throws IOException
	{
		JsonObject data = extractDataObject(json, "/5m");
		for (Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			int itemId;
			try
			{
				itemId = Integer.parseInt(entry.getKey());
			}
			catch (NumberFormatException ignored)
			{
				continue;
			}
			if (itemId <= 0 || !entry.getValue().isJsonObject())
			{
				continue;
			}

			JsonObject obj = entry.getValue().getAsJsonObject();
			Integer avgHigh = getPositiveInt(obj, "avgHighPrice");
			int highVol = getNonNegativeInt(obj, "highPriceVolume");
			Integer avgLow = getPositiveInt(obj, "avgLowPrice");
			int lowVol = getNonNegativeInt(obj, "lowPriceVolume");

			MarketPrice existing = priceMap.computeIfAbsent(itemId, id -> MarketPrice.builder()
				.itemId(id)
				.fetchedAtEpochSec(fetchedAtEpochSec)
				.build());

			existing.setAvgHighPrice5m(avgHigh);
			existing.setHighVolume5m(highVol);
			existing.setAvgLowPrice5m(avgLow);
			existing.setLowVolume5m(lowVol);
		}
	}

	/**
	 * Merges /1h stable rolling average pricing and volumes into the existing price map.
	 */
	public void merge1hJson(Map<Integer, MarketPrice> priceMap, String json, long fetchedAtEpochSec) throws IOException
	{
		JsonObject data = extractDataObject(json, "/1h");
		for (Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			int itemId;
			try
			{
				itemId = Integer.parseInt(entry.getKey());
			}
			catch (NumberFormatException ignored)
			{
				continue;
			}
			if (itemId <= 0 || !entry.getValue().isJsonObject())
			{
				continue;
			}

			JsonObject obj = entry.getValue().getAsJsonObject();
			Integer avgHigh = getPositiveInt(obj, "avgHighPrice");
			int highVol = getNonNegativeInt(obj, "highPriceVolume");
			Integer avgLow = getPositiveInt(obj, "avgLowPrice");
			int lowVol = getNonNegativeInt(obj, "lowPriceVolume");

			MarketPrice existing = priceMap.computeIfAbsent(itemId, id -> MarketPrice.builder()
				.itemId(id)
				.fetchedAtEpochSec(fetchedAtEpochSec)
				.build());

			existing.setAvgHighPrice1h(avgHigh);
			existing.setHighVolume1h(highVol);
			existing.setAvgLowPrice1h(avgLow);
			existing.setLowVolume1h(lowVol);
		}
	}

	private JsonObject extractDataObject(String json, String endpointName) throws IOException
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new IOException("Empty JSON payload from " + endpointName);
		}
		try
		{
			JsonElement rootElement = gson.fromJson(json, JsonElement.class);
			if (rootElement == null || !rootElement.isJsonObject())
			{
				throw new IOException("Malformed JSON root from " + endpointName);
			}
			JsonObject root = rootElement.getAsJsonObject();
			if (!root.has("data") || !root.get("data").isJsonObject())
			{
				throw new IOException("Missing 'data' object in " + endpointName);
			}
			return root.getAsJsonObject("data");
		}
		catch (JsonSyntaxException ex)
		{
			throw new IOException("Invalid JSON syntax from " + endpointName + ": " + ex.getMessage(), ex);
		}
	}

	String executeWithRetry(String url) throws IOException
	{
		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.header("Accept", "application/json")
			.get()
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			int code = response.code();
			if (response.isSuccessful() && response.body() != null)
			{
				ResponseBody body = response.body();
				return body.string();
			}
			throw new IOException("HTTP " + code + " from " + url);
		}
	}

	private static Integer getPositiveInt(JsonObject obj, String key)
	{
		if (obj.has(key) && !obj.get(key).isJsonNull())
		{
			try
			{
				int val = obj.get(key).getAsInt();
				return val > 0 ? val : null;
			}
			catch (Exception ignored)
			{
				return null;
			}
		}
		return null;
	}

	private static int getNonNegativeInt(JsonObject obj, String key)
	{
		if (obj.has(key) && !obj.get(key).isJsonNull())
		{
			try
			{
				int val = obj.get(key).getAsInt();
				return Math.max(0, val);
			}
			catch (Exception ignored)
			{
				return 0;
			}
		}
		return 0;
	}

	private static Long getPositiveLong(JsonObject obj, String key)
	{
		if (obj.has(key) && !obj.get(key).isJsonNull())
		{
			try
			{
				long val = obj.get(key).getAsLong();
				return val > 0 ? val : null;
			}
			catch (Exception ignored)
			{
				return null;
			}
		}
		return null;
	}
}

