		g2.setFont(new Font("SansSerif", Font.BOLD, 9));
		FontMetrics fm = g2.getFontMetrics();
		String label = "ALCH";
		g2.drawString(label, cx - fm.stringWidth(label) / 2, 51 + 11);

		g2.dispose();
		return img;
	}
